import { isValidIBAN } from "ibantools";

/** Validate a recipient IBAN string. Returns { valid: true } or { valid: false, error: string }. */
export function validateIban(iban) {
  if (typeof iban !== "string" || iban.trim() === "") {
    return { valid: false, error: "recipient is required" };
  }
  if (!isValidIBAN(iban.trim())) {
    return { valid: false, error: "invalid IBAN" };
  }
  return { valid: true };
}

